<script setup lang="ts">
import { onMounted, ref } from "vue"; import { ElMessage } from "element-plus"; import { http } from "../api";
const takes=ref<any[]>([]), active=ref<any>(); async function load(){takes.value=await http.get("/stock-takes") as unknown as any[]} async function create(){active.value=await http.post("/stock-takes",{scope_type:"all"});await load()} async function save(){await http.put(`/stock-takes/${active.value.id}/items`,{items:active.value.items.map((x:any)=>({part_id:x.part_id,actual_quantity:x.actual_quantity}))});ElMessage.success("实盘数量已保存")} async function post(){await save();active.value=await http.post(`/stock-takes/${active.value.id}/post`);ElMessage.success("盘点已过账");await load()} function selectTake(row:any){active.value=row} onMounted(load);
</script>
<template><div class="page-actions"><span>按账面数冻结后录入实盘数，期间出入库会在过账时自动计入。</span><el-button type="primary" @click="create">新建全库盘点</el-button></div><div v-if="active" class="panel"><div class="page-actions"><strong>{{active.take_no}}</strong><div><el-button @click="save">暂存</el-button><el-button type="primary" @click="post">过账</el-button></div></div><el-table :data="active.items"><el-table-column prop="part_id" label="零件ID"/><el-table-column prop="book_quantity" label="冻结账面数"/><el-table-column label="实盘数"><template #default="{row}"><el-input-number v-model="row.actual_quantity" :min="0" :precision="3"/></template></el-table-column></el-table></div><div v-else class="panel"><el-table :data="takes" @row-click="selectTake"><el-table-column prop="take_no" label="盘点单号"/><el-table-column prop="started_at" label="开始时间"/><el-table-column prop="status" label="状态"/><el-table-column prop="posted_at" label="过账时间"/></el-table></div></template>
